(function(){
  function parseCsv(text){
    text=String(text).replace(/\r\n/g,'\n').replace(/\r/g,'\n');
    var rows=[], row=[], f='', q=false, i=0;
    while(i<text.length){ var c=text[i];
      if(q){ if(c==='"'){ if(text[i+1]==='"'){f+='"';i++;} else q=false; } else f+=c; }
      else { if(c==='"') q=true; else if(c===','){ row.push(f); f=''; } else if(c==='\n'){ row.push(f); rows.push(row); row=[]; f=''; } else f+=c; }
      i++; }
    if(f.length||row.length){ row.push(f); rows.push(row); }
    while(rows.length && rows[rows.length-1].length===1 && rows[rows.length-1][0]==='') rows.pop();
    if(!rows.length) return {value:{columns:[],rows:[]}};
    var cols=rows[0], data=rows.slice(1).map(function(r){ var o={}; for(var k=0;k<cols.length;k++) o[cols[k]]=r[k]!==undefined?r[k]:''; return o; });
    return {value:{columns:cols, rows:data}};
  }
  function splitWhere(s){ return s.split(/\s+and\s+/i).map(function(p){
    var m=p.match(/(\w+)\s*(=|!=|<>|>=|<=|>|<|like|contains)\s*('([^']*)'|"([^"]*)"|([\w.\-]+))/i);
    if(!m) return {col:'',op:'=',val:''}; return {col:m[1], op:m[2].toLowerCase(), val:m[4]||m[5]||m[6]||''}; }); }
  function runSql(text, sql){
    var p=parseCsv(text); sql=String(sql||'').replace(/;+\s*$/,'');
    var m=sql.match(/select\s+(.+?)\s+from\s+\w+/i); if(!m) return {error:'仅支持 SELECT ... FROM t'};
    var sel=m[1].trim();
    var rest=sql.slice(sql.toLowerCase().indexOf('from')+4).replace(/^\s*\w+/,'');
    var where='', order='', limit=0;
    var wm=rest.match(/where\s+(.*?)(?:\s+order\s+by|\s+limit|$)/is); if(wm) where=wm[1].trim();
    var om=rest.match(/order\s+by\s+(\w+)\s*(asc|desc)?/i); if(om) order=om[1]+' '+(om[2]||'asc');
    var lm=rest.match(/limit\s+(\d+)/i); if(lm) limit=+lm[1];
    var cols = sel==='*'? p.value.columns : sel.split(',').map(function(s){return s.trim();});
    var rows=p.value.rows;
    if(where){ var conds=splitWhere(where);
      rows=rows.filter(function(r){ return conds.every(function(c){ var v=r[c.col]; var cv=c.val;
        if(c.op==='like'||c.op==='contains') return String(v).toLowerCase().indexOf(cv.toLowerCase())>=0;
        if(c.op==='=') return String(v)===cv;
        if(c.op==='!='||c.op==='<>') return String(v)!==cv;
        var a=parseFloat(v), b=parseFloat(cv);
        if(c.op==='>')return a>b; if(c.op==='<')return a<b; if(c.op==='>=')return a>=b; if(c.op==='<=')return a<=b; return false; }); }); }
    if(order){ var pa=order.split(' '), col=pa[0], dir=(pa[1]&&pa[1].toLowerCase()==='desc')?-1:1;
      rows=rows.slice().sort(function(x,y){ var a=x[col],b=y[col]; if(a===b)return 0; if(a===undefined)return 1; if(b===undefined)return -1; return (a<b?-1:1)*dir; }); }
    if(limit) rows=rows.slice(0,limit);
    return {value:{columns:cols, rows:rows}};
  }
  var API={parseCsv:parseCsv, runSql:runSql};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__QsvForge__=API;
})();
